import type { OrderResponse } from './lib-types.js'

/** Maps /order error codes (transaction empty) to user copy. */
export function describeOrderError(o: Pick<OrderResponse, 'errorCode' | 'errorMessage'>) {
  const map: Record<number, string> = {
    1: 'Insufficient balance for this swap.',
    2: 'Not enough SOL to pay network fees. Keep at least 0.01 SOL.',
    3: 'Amount too small for this route. Try a larger amount.',
  }
  return (o.errorCode && map[o.errorCode]) || o.errorMessage || 'Could not build the swap. Try again.'
}

/** User-facing error copy. Every message states whether funds were debited. */
export function friendlyError(msg: string) {
  const m = msg.toLowerCase()
  if (m.includes('user rejected') || m.includes('rejected the request')) return 'You rejected the transaction in your wallet. No funds were debited.'
  if (m.includes('slippage') || m.includes('0x1771') || m.includes('6001')) return 'Price moved beyond your slippage tolerance. No funds were debited. Try again or raise slippage in settings.'
  if (m.includes('insufficient')) return 'Insufficient balance for this swap, including network fees. No funds were debited.'
  if (m.includes('expired') || m.includes('-1005') || m.includes('block height')) return 'The quote expired before the transaction landed. No funds were debited. Please try again.'
  if (m.includes('failed to land') || m.includes('-1000')) return 'The network was congested and the transaction did not land. No funds were debited. Please try again.'
  return `${msg} If the transaction did not land, no funds were debited.`
}
